{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "initial",
  "supportive_card_ids": ["C10", "C15", "C24", "C03", "C13", "C01", "C04", "C26"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C10", "C15", "C24", "C03", "C13"],
  "claims": [
    {
      "claim": "Cladribine, a 2-halogenated adenine nucleoside, showed absolute oral bioavailability of 36–46% in fasted patients, supporting F ≥20% for the analogous 2-fluoroadenine nucleoside.",
      "card_ids": ["C10", "C15", "C24"]
    },
    {
      "claim": "Didanosine, a purine nucleoside with relatively low fasted F (22–28%), still exceeded the 20% threshold, indicating that even poorly absorbed purine nucleosides can meet the threshold.",
      "card_ids": ["C03", "C13"]
    },
    {
      "claim": "Polar pyrimidine nucleosides such as lamivudine and emtricitabine had high fasted oral bioavailability (69–95% and 92%), showing that high polarity does not preclude F ≥20%.",
      "card_ids": ["C01", "C04", "C26"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "current_gold_voting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C10", "C15", "C24", "C03", "C13", "C01", "C04", "C26"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement is available for the query molecule itself.",
    "The query sugar ring appears to be a pyranose rather than the furanose nucleosides in most records, so structural transferability is moderate rather than exact.",
    "Transporter-mediated absorption, intestinal metabolism, and first-pass extraction for the query are not directly measured.",
    "The physicochemical prior is mixed, with unfavorable passive permeability but favorable solubility and possible nucleoside-transporter involvement."
  ],
  "decision_summary": "The query is a polar 2-fluorinated adenine nucleoside. The most relevant nucleoside analog records, especially cladribine (36–46%) and didanosine (22–28%), all show absolute oral bioavailability at or above the 20% threshold, and polar nucleosides such as lamivudine and emtricitabine show high F. No affirmative evidence supports F <20%, so the better-supported prediction is high."
}

